ort function getSyncLifecycle<T>(Component: ComponentType<T>, options: ComponentDecoratorOptions) {\n78:   return () => Promise.resolve(getLifecycle(Component, options));\n79: }\n80: \n81: /**\n82:  * @deprecated Use getAsyncLifecycle instead.\n83:  */\n84: export const getAsyncExtensionLifecycle = getAsyncLifecycle;\n85: \n\n(End of file - 85 lines total)\n</content>"}]}]},"parent_tool_use_id":null,"session_id":"1b8aef6b-c486-45f3-b6b1-a81f2257b733","uuid":"bc4f2c80-4981-4479-8598-259f6c3fd498","timestamp":"2026-10-19T16:51:04.104Z","tool_use_result":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-core</repo>\n<path>packages/framework/esm-react-utils/src/getLifecycle.ts</path>\n<url>undefined</url>\n<content>\n1: /** @module @category Framework */\n2: import type { ComponentType } from 'react';\n3: import React from 'react';\n4: import ReactDOMClient from 'react-dom/client';\n5: import type { AppProps } from 'single-spa';\n6: import singleSpaReact, { type ReactAppOrParcel } from 'single-spa-react';\n7: import type { ComponentDecoratorOptions } from './openmrsComponentDecorator';\n8: import { openmrsComponentDecorator } from './openmrsComponentDecorator';\n9: \n10: /**\n11:  * Creates a single-spa lifecycle object for a React component. The component is\n12:  * wrapped with the OpenMRS component decorator which provides standard functionality\n13:  * like error boundaries, configuration, and extension support.\n14:  *\n15:  * @param Component The React component to create a lifecycle for.\n16:  * @param options Configuration options for the OpenMRS component decorator.\n17:  * @returns A single-spa lifecycle object with bootstrap, mount, and unmount functions.\n18:  *\n19:  * @example\n20:  * ```ts\n21:  * import { getLifecycle } from '@openmrs/esm-framework';\n22:  * import MyComponent from './MyComponent';\n23:  * export const lifecycle = getLifecycle(MyComponent, { featureName: 'my-feature', moduleName: '@openmrs/esm-my-app' });\n24:  * ```\n25:  */\