sAppName: string, fullComponentName: string): Promise<LifeCycles> {\n36:   const poundIndex = fullComponentName.indexOf('#');\n37:   const isNamespaced = poundIndex >= 0;\n38:   const appName = isNamespaced ? fullComponentName.substring(0, poundIndex) : routesAppName;\n39:   const componentName = isNamespaced ? fullComponentName.substring(poundIndex + 1) : fullComponentName;\n40: \n41:   const module = await importDynamic<Module>(appName);\n42: \n43:   if (module && Object.hasOwn(module, componentName) && typeof module[componentName] === 'function') {\n44:     return initializeApp(appName, module).then(() => module[componentName]());\n45:   } else {\n46:     if (!module) {\n47:       console.warn(`Unknown app ${appName} for ${fullComponentName} defined in ${routesAppName}'s routes.json`);\n48:     } else if (module && Object.hasOwn(module, componentName)) {\n49:       console.warn(`The export ${fullComponentName}, defined in ${routesAppName}'s routes.json, is not a function`);\n50:     } else {\n51:       console.warn(\n52:         `${appName} does not define a component called \"${componentName}\", referenced in ${routesAppName}'s routes.json. This cannot be loaded.`,\n53:       );\n54:     }\n55:   }\n56: \n57:   return emptyLifecycle;\n58: }\n59: \n60: const emptyLifecycle: LifeCycles<never> = {\n61:   bootstrap() {\n62:     return Promise.resolve();\n63:   },\n64:   mount() {\n65:     return Promise.resolve();\n66:   },\n67:   unmount() {\n68:     return Promise.resolve();\n69:   },\n70: };\n71: \n72: /**\n73:  * This function can be used to manually initialize an application without waiting for the\n74:  * framework to load it. This can sometimes be helpful if the framework doesn't load code\n75:  * at the point you think is appropriate.\n76:  *\n77:  * This will ensure that the module is available and that it's `startupApp()` function (if\n78:  * any) will be called. Note that these are only guaranteed to be complete once the Promise\n79:  * returned from the 